let root;let passed=0;let screenCount=0;
const pause=()=>new Promise(resolve=>setTimeout(resolve,25));
async function test(label,fn){await fn();passed++;console.log('PASS '+label);}
async function render(path,clear=false){if(root)await act(async()=>root.unmount());if(clear)localStorage.clear();history.replaceState(null,'','/original.html?demo=1#'+path);root=createRoot(document.getElementById('root'));await act(async()=>{root.render(React.createElement(App));await pause();});}
const text=()=>document.body.textContent;
const buttons=()=>[...document.querySelectorAll('button')];
async function click(label,exact=false){const button=buttons().find(b=>(exact?b.textContent.trim()===label:b.textContent.includes(label))||b.getAttribute('aria-label')===label);assert.ok(button,'Button missing: '+label);assert.ok(!button.disabled,'Button disabled: '+label);await act(async()=>{button.click();await pause();});}
async function input(selector,value){const element=document.querySelector(selector);assert.ok(element,'Input missing '+selector);await act(async()=>{Object.getOwnPropertyDescriptor(element instanceof HTMLTextAreaElement?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set.call(element,value);element.dispatchEvent(new Event('input',{bubbles:true}));element.dispatchEvent(new Event('change',{bubbles:true}));await pause();});}
async function back(){await act(async()=>{history.back();await pause();});}
