async function renderLiveBot(id,clear=false){if(root)await act(async()=>root.unmount());if(clear)localStorage.clear();root=createRoot(document.getElementById('root'));await act(async()=>{root.render(React.createElement(BotChat,{bot:bots.aiBot(id),onBack:()=>{},endpoint:'/api/ai-chat'}));await pause();});}
async function radio(value){const field=[...document.querySelectorAll('input[type="radio"]')].find(field=>field.value===value);assert.ok(field,'Radio missing '+value);await act(async()=>{field.click();await pause();});}
async function selectLabel(label,value){const field=[...document.querySelectorAll('label')].find(l=>l.childNodes[0]?.textContent.trim()===label)?.querySelector('select');assert.ok(field,'Select missing '+label);await act(async()=>{Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set.call(field,value);field.dispatchEvent(new Event('change',{bubbles:true}));await pause();});}

