 await test('all sixteen games explain their goal, complete, resume, and award XP once',async()=>{
   for(const id of nav.gameIds){
     await render('/chatgames/'+id,true);
     assert.ok(text().includes('How it works')&&text().includes('YOU’LL LEAVE WITH'),id);
     assert.ok(!document.querySelector('textarea'),'Game starts with an explanation: '+id);
     await click('Start game',true);
     for(let turn=0;turn<8&&!text().includes('Game complete');turn++){
       const field=document.querySelector('textarea[aria-label="Game response"]');
       const choices=[...document.querySelectorAll('.games-choice-list button')];
       if(field)await input('textarea[aria-label="Game response"]','A thoughtful answer for '+id+' step '+turn);
       else if(choices.length)await act(async()=>{choices[0].click();await pause();});
       const next=document.querySelector('.games-session-footer .mobile-primary-button');
       assert.ok(next&&!next.disabled,'No clear next action in '+id);
       await act(async()=>{next.click();await pause();});
     }
     assert.ok(text().includes('Game complete'),'Incomplete: '+id);
     const balance=state.readDeviceValue('xp-balance',0);
     await render('/chatgames/'+id);
     assert.ok(text().includes('Game complete'),'Lost result: '+id);
     assert.equal(state.readDeviceValue('xp-balance',0),balance,'Duplicate reward: '+id);
     const editButton=document.querySelector('.games-results button');
     assert.ok(editButton,'Result should be editable: '+id);
     await act(async()=>{editButton.click();await pause();});
     const editField=document.querySelector('textarea[aria-label="Game response"]');
     if(editField)await input('textarea[aria-label="Game response"]','An updated saved answer.');
     await click('Save change',true);
     assert.ok(text().includes('Game complete'),'Edit did not return to result: '+id);
     assert.equal(state.readDeviceValue('xp-balance',0),balance);
     await click('Back to Games');assert.equal(location.hash,'#/chatgames');
   }
 });
