 await test('all twelve quick chat tools have a reachable saved outcome',async()=>{
   const tools=['Fate Roll','Hot Take','Question Swap','Two Truths & a Mask','Conversation Question','Share Your Mood','Small Challenge','Story Chain','Kind Response','One Honest Answer','What If?','Quick Trivia'];
   for(const label of tools){
     await render('/chat/1',true);await click('Chat games');await click('Play '+label);
     if(label==='Share Your Mood'){await click('Calm',true);await click('Drop Mood into Chat');assert.deepEqual(state.readDeviceValue('shared-chat-mood:1',[]),['Calm']);continue;}
     const latest=()=>state.readDeviceValue('chat:1',[]).at(-1).game;
     const card=document.querySelector('[data-quick-game="'+latest().type+'"]');assert.ok(card);
     if(label==='Fate Roll'){await click('Roll die');assert.ok(latest().rolled);}
     else if(label==='Hot Take'){await click('Agree');assert.equal(latest().status,'resolved');}
     else if(label==='Question Swap'){if(!document.querySelector('input[aria-label="Question answer"]'))await click('Write an answer');await input('input[aria-label="Question answer"]','A small answer with a clear ending.');await click('Save question answer');assert.equal(latest().status,'resolved');}
     else if(label==='Conversation Question'){await click(latest().options[1],true);assert.equal(latest().status,'resolved');assert.equal(latest().choice,'Explore a big idea');}
     else if(label==='Two Truths & a Mask'){await click(latest().statements[0],true);assert.equal(latest().status,'resolved');}
     else if(label==='Small Challenge'){await click('Try this',true);assert.equal(latest().status,'accepted');}
     else if(label==='Story Chain'){for(let index=0;index<3;index++){await input('textarea[aria-label="Story line"]','A line '+index);await click('Add line');}assert.ok(latest().sealed);}
     else if(label==='Kind Response'){await click('I hear you');assert.equal(latest().myReaction,'witnessed');}
     else if(label==='One Honest Answer'){await input('input[aria-label="Honest answer"]','Something I enjoy learning.');await click('Send',true);assert.equal(latest().status,'revealed');assert.equal(latest().similarity,undefined);}
     else if(label==='What If?'){await click("No, it won't",true);assert.equal(latest().status,'resolved');assert.equal(latest().outcome,undefined);}
     else {await click(latest().options[0],true);assert.equal(latest().status,'resolved');}
     await render('/chat/1');assert.ok(state.readDeviceValue('chat:1',[]).at(-1).game,'Outcome lost for '+label);
   }
 });
